static <T> int transfer(List<T> source, List<T> destination, Predicate<T> predicate) {
    int moved = 0;
    Iterator<T> it = source.iterator();
    while (it.hasNext()) {
        T item = it.next();
        if (predicate.test(item)) {
            destination.add(item);
            it.remove();
            moved++;
        }
    }
    return moved;
}

