Predicate<Object> notNull = Objects::nonNull;
List<String> maybe = new ArrayList<>(List.of("x", "y"));
List<String> kept = new ArrayList<>();
checkEq(transfer(maybe, kept, notNull), 2);
check(maybe.isEmpty());
checkEq(kept, List.of("x", "y"));

