                        List<? super T> destination,
                        Predicate<? super T> predicate) {
    int moved = 0;
    Iterator<? extends T> it = source.iterator();
    while (it.hasNext()) {
        T item = it.next();
        if (predicate.test(item)) {
            destination.add(item);
            it.remove();
            moved++;
        }
    }
    return moved;
}
